const drawer=document.getElementById('usxDrawer');
const ae=document.activeElement;
const typing = drawer && ae && drawer.contains(ae) && (ae.tagName==='TEXTAREA'||ae.tagName==='INPUT');
if(!typing) fillUsxCase();
