function renderUsxKpis(mountId){
const row=document.getElementById(mountId||'usxKpis'); if(!row) return;
const q=usQueue(), prog=usInProgress(), needs=usNeedsInfo(), done=usCompletedToday(), reqs=usRequestsToday();
const next=q[0];


const A=CKPI_AC;
const cards=[
{k:'usreq',  lab:'Requests Today', ac:A.cyan, raw:reqs.length, val:String(reqs.length),
chip:'Today', sub:'Submitted since midnight'},
{k:'uswait', lab:'Waiting', ac:q.length?A.amber:A.neutral, raw:q.length, val:String(q.length),
chip:q.length?(q.length+' active'):'Clear', sub:q.length?'In the IM queue':'Queue is clear'},
{k:'usnext', lab:'Next Patient', ac:next?A.cyan:A.neutral, isName:true, val:next?next.name:'—',
chip:next?'Next':'None',
sub:next?(PRIO_LABEL[next.prio]+' · waiting '+fmtWait(usWaitMin(next))):'No one waiting'},
{k:'usprog', lab:'In Progress', ac:prog.length?A.cyan:A.neutral, raw:prog.length, val:String(prog.length),
chip:prog.length?'Scanning':'Idle', sub:prog.length?prog.map(p=>p.name).join(', '):'No active scan'},
{k:'usinfo', lab:'Needs Information', ac:needs.length?A.amber:A.neutral, raw:needs.length, val:String(needs.length),
chip:needs.length?'Action needed':'All clear', sub:needs.length?'Incomplete requests':'All requests complete'},
{k:'usdone', lab:'Completed Today', ac:done.length?A.green:A.neutral, raw:done.length, val:String(done.length),
chip:'Today', sub:'Since hospital midnight'}
];
ckpiSample('usq',cards);
row.innerHTML=cards.map((c,i)=>ckpiCard(c,i,'usq')).join('');
}

function usxHistChips(p,max){
const a=p.reasonProblems||[];
if(!a.length) return'<span class="usx-empty">No presenting problems recorded</span>';
let h=a.slice(0,max).map(pr=>'<span class="usx-chip">'+bcEsc(formatProblem(pr))+'</span>').join('');
if(a.length>max) h+='<span class="usx-chip more">+'+(a.length-max)+'</span>';
return h;
}
function usxDxLine(p){
const u=p.ultrasound;
const parts=usDiagnostics(p).slice();
if(u.diagnosticsNotes&&u.diagnosticsNotes.trim()) parts.push(u.diagnosticsNotes.trim());
return parts.join(' · ');
}
