const US_WAIT_WARN=45;
const UST_RAIL_TARGET=30, UST_RAIL_TPCT=82, UST_RAIL_OVER=6;
const UST_CHECK='<svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
const UST_CLOCK='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5.3l3.3 2"/></svg>';
const UST_GRIP='<svg viewBox="0 0 14 18" fill="currentColor"><circle cx="4" cy="3" r="1.5"/><circle cx="10" cy="3" r="1.5"/><circle cx="4" cy="9" r="1.5"/><circle cx="10" cy="9" r="1.5"/><circle cx="4" cy="15" r="1.5"/><circle cx="10" cy="15" r="1.5"/></svg>';
function ustInitial(p){ return bcEsc(((p.name||'?').trim()[0]||'?').toUpperCase()); }


function usAvatar(p){
const pc=PRIO_CLR[p.prio]||PRIO_CLR[3];
return`<div class="cl-photo patient-medallion ${spCls(p)}" style="--gc:${pc.c};--gcrgb:${pc.rgb}">${monoInner(p)}</div>`;
}
function ustCQ(p){ const cq=(p.ultrasound.clinicalQuestion||'').trim(); return cq?bcEsc(cq):'<i>Not provided</i>'; }
function ustChips(p,max,cls){
const a=p.reasonProblems||[];
if(!a.length) return'<span class="'+cls+' none">No presenting problems recorded</span>';
let h=a.slice(0,max).map(pr=>'<span class="'+cls+'">'+bcEsc(formatProblem(pr))+'</span>').join('');
if(a.length>max) h+='<span class="'+cls+'">+'+(a.length-max)+'</span>';
return h;
}


function ustHandoffRail(u){
const stages=[
{l:'Requested',t:u.requestedAt||u.createdAt},
{l:'Accepted', t:u.acceptedAt},
{l:'Started',  t:u.startedAt},
{l:'Completed',t:u.completedAt}
];
let last=-1, next=-1;
stages.forEach((s,i)=>{ if(s.t) last=i; else if(next<0) next=i; });
const pct=last<0?0:(last+0.5)*(100/stages.length);
const cls=i=>stages[i].t?' is-done':(i===next?' is-next':'');
const nodes=stages.map((s,i)=>`<div class="nextup-node${cls(i)}"><span class="nextup-dot"></span></div>`).join('');
const labels=stages.map((s,i)=>`<div class="nextup-stage${cls(i)}">`
+`<div class="nextup-stage-name">${s.l}</div>`
+`<div class="nextup-stage-time">${s.t?bcEsc(fmtTime(s.t)):'—'}</div></div>`).join('');
return`<div class="nextup-handoff" aria-label="Requested, Accepted, Started, Completed">
      <div class="nextup-rail-wrap">
        <div class="nextup-rail" style="left:${pct}%"></div>
        ${last<0?'':`<div class="nextup-rail-progress" style="width:${pct}%"></div>`}
        <div class="nextup-nodes">${nodes}</div>
      </div>
      <div class="nextup-labels">${labels}</div>
    </div>`;
}



