function renderUstScanning(){
const el=document.getElementById('umScan'); if(!el) return;
const prog=usInProgress();
if(!prog.length){
el._sig=null;
el.innerHTML='<div class="um-eyebrow">Currently Scanning</div><div class="um-quiet"><b>No active scan</b><span>Take the next patient from the queue to begin.</span></div>';
return;
}



const sig=prog.map(p=>{const u=p.ultrasound; return p.id+'~'+(u.performingDoctorId||u.performingDoctor||'')
+'~'+(u.acceptedAt?fmtTime(u.acceptedAt):'')+'~'+(u.startedAt?fmtTime(u.startedAt):'')
+'~'+(u.clinicalQuestion||'');}).join(',');
if(el._sig===sig){
el.querySelectorAll('.ums-detail').forEach(c=>{
const p=prog.find(x=>x.id===c.dataset.open); if(!p) return;
const t=c.querySelector('.timeline-label.now .time'); if(t) t.textContent=fmtWait(usScanMin(p));
});
return;
}
el._sig=sig;
el.innerHTML=`<div class="um-eyebrow">Currently Scanning<span class="cnt">${prog.length}</span></div>`
+prog.map((p,i)=>{
const su=p.ultrasound;
return`<div class="ums-detail ultrasound-scan-card" data-open="${p.id}">
      <div class="ultrasound-scan-head">
        <div class="ultrasound-scan-title">${bcEsc(p.name||'')}</div>
        <div class="head-right">
          <div class="live"><span class="live-dot"></span> LIVE</div>
          <button class="detail-chevron" type="button" aria-label="Open patient details">
            <svg viewBox="0 0 24 24" aria-hidden="true">
              <path d="M9 6l6 6-6 6"></path>
            </svg>
          </button>
        </div>
      </div>
      <div class="timeline">
        ${umsSpark(i)}
        <div class="timeline-labels">
          <div class="timeline-label">
            <div class="label">Taken</div>
            <div class="time">${su.acceptedAt?fmtTime(su.acceptedAt):'—'}</div>
          </div>
          <div class="timeline-label">
            <div class="label">Started</div>
            <div class="time">${su.startedAt?fmtTime(su.startedAt):'—'}</div>
          </div>
          <div class="timeline-label now">
            <div class="label">Now</div>
            <div class="time">${fmtWait(usScanMin(p))}</div>
          </div>
        </div>
      </div>
      <div class="ultrasound-scan-footer">
        <span class="q">${ustCQ(p)}</span>
        <span class="doctor">${bcEsc(drName(su.performingDoctor))}</span>
      </div>
    </div>`;}).join('');
el.querySelectorAll('.ums-detail').forEach(d=>d.addEventListener('click',()=>openUsxCase(d.dataset.open)));
drawUltrasoundTimeline(el);
}

 
function renderUstRoadmap(){
const el=document.getElementById('umRoad'); if(!el) return;
const q=usQueue(), canEdit=usCanEdit();
const maxW=Math.max(1,...q.map(p=>usWaitMin(p)));
const nextIdx=q.findIndex(p=>usEff(p)!=='accepted');
el.innerHTML=`
    <div class="um-rhead"><h3 class="um-title">Ultrasound Queue</h3>
      <span class="note">${canEdit?'Bar length = time waiting · drag to reorder':'Bar length = time waiting · view only'}</span></div>
    ${q.length?`<div class="um-rows" id="umRows">${q.map((p,i)=>{
      const u=p.ultrasound, w=usWaitMin(p), acc=usEff(p)==='accepted';
      const tone=w>=US_WAIT_WARN?'warn':'';
      // Wait rail scale from pravix_ultrasound_queue_rail.html: the 30-minute
      // target sits at 82% and the remaining 18% is the overtime reserve, worth
      // about six more minutes. Past 36m the marker parks at the end and the
      // label keeps showing the real figure.
      const over=w>UST_RAIL_TARGET;
      const pos=Math.min(100, over
        ? UST_RAIL_TPCT + Math.min((w-UST_RAIL_TARGET)/UST_RAIL_OVER,1)*(100-UST_RAIL_TPCT)
        : Math.max(0,Math.min(UST_RAIL_TPCT,(w/UST_RAIL_TARGET)*UST_RAIL_TPCT)));
      // the dot and hover rail take the shared priority colour, same map Client
      // Display and Next Up use — no second priority palette anywhere
      const pc=PRIO_CLR[p.prio]||PRIO_CLR[3];
      return `<div class="um-rrow ${i===nextIdx?'next':''}" data-pid="${p.id}" style="--fc:${pc.c};--fcrgb:${pc.rgb}" ${canEdit?'draggable="true"':''}>
        ${canEdit?`<button type="button" class="um-rgrip us-move" data-move="${p.id}" title="Drag to reorder, or use the arrow keys" aria-label="Move ${bcEsc(p.name||'')} in the queue — position ${i+1} of ${q.length}. Arrow keys move it.">${UST_GRIP}</button>`:'<span class="um-rgrip"></span>'}
        <span class="um-rdot"></span>
        <div class="um-rbody">
          <div class="um-rtitle"><b><button type="button" class="pvx-open us-open" aria-label="Open ultrasound case: ${bcEsc(p.name||'')}">${bcEsc(p.name||'')}</button></b>
            <span class="prio prio-${p.prio}" style="width:19px;height:19px;font-size:0.5625rem;flex:0 0 auto">${PRIO[p.prio].l}</span></div>
          <div class="um-rsub">#${i+1} · ${acc?bcEsc(drName(u.acceptedBy)):'Unassigned'}</div>
          <div class="um-rflags">
            ${i===nextIdx?'<span class="um-rchip c-next">Next</span>':''}
            ${acc?'<span class="um-rchip c-acc">Accepted</span>':''}
            ${tone?'<span class="um-rchip c-wait">Long wait</span>':''}
          </div>
        </div>
        <div class="wait-rail ${over?'over':''}">
          <div class="target-label">30m target</div>
          <div class="rail"></div>
          <div class="elapsed ${i===nextIdx?'next':''}" style="width:${Math.min(pos,UST_RAIL_TPCT).toFixed(2)}%"></div>
          ${over?`<div class="overtime" style="width:${(pos-UST_RAIL_TPCT).toFixed(2)}%"></div>`:''}
          <div class="marker ${i===nextIdx?'next':''}" style="left:${pos.toFixed(2)}%"></div>
          <div class="wait-label" style="left:${pos.toFixed(2)}%">${fmtWait(w)}</div>
          <div class="rail-start">0m</div>
          <div class="target-tick-label">30m</div>
          <div class="rail-end">36m+</div>
        </div>
        <span class="um-rwait ${tone}">${fmtWait(w)}</span></div>`;}).join('')}</div>`
:'<div class="um-quiet" style="padding:34px 14px"><b>No patients waiting</b><span>Requests submitted from Flow enter the queue automatically.</span></div>'}`;
  const rows=document.getElementById('umRows'); if(!rows) return;
  rows.querySelectorAll('.um-rrow').forEach(r=>{
    r.addEventListener('click',()=>{ if(!r.classList.contains('dragging')) openUsxCase(r.dataset.pid); });
    if(canEdit){
      r.addEventListener('dragstart',e=>{ _usxDrag=r.dataset.pid; r.classList.add('dragging'); e.dataTransfer.effectAllowed='move'; });
      r.addEventListener('dragend',()=>{ r.classList.remove('dragging'); _usxDrag=null; renderUltrasound(); });
    }
  });
  if(!rows._umWired){
    rows._umWired=true;
    rows.addEventListener('dragover',e=>{
      if(!_usxDrag) return; e.preventDefault();
      const drag=rows.querySelector('.um-rrow.dragging'); if(!drag) return;
      const els=[...rows.querySelectorAll('.um-rrow:not(.dragging)')];
      const after=els.reduce((cl,ch)=>{ const b=ch.getBoundingClientRect(); const off=e.clientY-b.top-b.height/2;
        return (off<0&&off>cl.off)?{off:off,el:ch}:cl; },{off:-Infinity,el:null}).el;
      if(after==null) rows.appendChild(drag); else rows.insertBefore(drag,after);
    });
    rows.addEventListener('drop',e=>{
      if(!_usxDrag) return; e.preventDefault();
      const _pvxQ0=pvxQueueSnap(); [...rows.querySelectorAll('.um-rrow')].forEach((c,i)=>{ const p=PATIENTS.find(x=>x.id===c.dataset.pid); if(p&&p.ultrasound) p.ultrasound.queuePosition=i+1; });
      _usxDrag=null;
      pvxQueueUndo(_pvxQ0);
      renderAll();
    });
  }
}

