/* ── AVERAGE WAIT — live average across the current queue ── */
/* ── AVG WAIT — pravix_avg_wait_card.html, wired to the live queue ───────────
   The card's markup, styling and its two animations are that file's code. Every
   figure here comes from usQueue() — the same list that draws the queue rows —
   so the two can never disagree. The prototype's LIVE badge is deliberately not
   carried over; Currently Scanning owns that indicator.                      */
const UST_AVG_TARGET=30, UST_AVG_NEAR=25;
const UST_AVG_ICONS={
  ok:'<path d="M5 12l4 4 10-10"></path>',
  at:'<path d="M5 12l4 4 10-10"></path>',
  near:'<circle cx="12" cy="12" r="9"></circle><path d="M12 7v5.2l3.2 2"></path>',
  over:'<circle cx="12" cy="12" r="9"></circle><path d="M12 7.6v5.2"></path><path d="M12 16.4v.01"></path>',
  idle:'<circle cx="12" cy="12" r="9"></circle><path d="M8.4 12h7.2"></path>'
};
function usAvgStatus(avg){
  if(avg===null) return {k:'idle',t:'Queue Clear',s:'No patients currently waiting',d:''};
  if(avg>UST_AVG_TARGET)  return {k:'over',t:'Above Target',s:'Average wait has exceeded the 30m target',d:fmtWait(avg-UST_AVG_TARGET)+' Over Target'};
  if(avg===UST_AVG_TARGET)return {k:'at',  t:'At Target',   s:'Average wait is exactly at the 30m target',d:'At Target'};
  if(avg>=UST_AVG_NEAR)   return {k:'near',t:'Approaching Target',s:'Average wait is nearing the 30m target',d:fmtWait(UST_AVG_TARGET-avg)+' Under Target'};
  return {k:'ok',t:'Within Target',s:'Current queue remains on pace',d:fmtWait(UST_AVG_TARGET-avg)+' Under Target'};
}
/* the prototype's soft number swap, taking the already-formatted string this app
   uses (fmtWait reads "1h 5m" past the hour) instead of a raw minute count */
function updateAvgWait(valueEl,text){
  if(!valueEl || valueEl.textContent===text) return;
  valueEl.classList.add('is-updating');
  setTimeout(function(){
    valueEl.textContent=text;
    requestAnimationFrame(function(){ valueEl.classList.remove('is-updating'); });
  },140);
}
function renderUstAvg(){
  const el=document.getElementById('umAvg'); if(!el) return;
  const waits=usQueue().map(p=>usWaitMin(p)), n=waits.length;
  const avg=n?Math.round(waits.reduce((a,b)=>a+b,0)/n):null;
  const lo=n?Math.min(...waits):null, hi=n?Math.max(...waits):null;
  // the marker reads the average against the spread it sits in, clamped so it
  // never rides off either end of the track
  const pos=!n?0:(hi===lo?50:Math.max(3,Math.min(97,((avg-lo)/(hi-lo))*100)));
  const st=usAvgStatus(avg), avgTxt=avg===null?'—':fmtWait(avg);
  const sig=n+'|'+st.k;
  if(el._sig===sig){                       // same shape — slide the numbers, keep the sweep running
    updateAvgWait(el.querySelector('.value'),avgTxt);
    const set=(s,v)=>{const x=el.querySelector(s); if(x) x.textContent=v;};
    set('.range-stat:not(.right) .range-value',lo===null?'—':fmtWait(lo));
    set('.range-stat.right .range-value',hi===null?'—':fmtWait(hi));
    set('.delta',st.d);
    ['.track-fill','.track-glow'].forEach(s=>{const x=el.querySelector(s); if(x) x.style.width=pos.toFixed(2)+'%';});
    ['.avg-marker','.avg-tag'].forEach(s=>{const x=el.querySelector(s); if(x) x.style.left=pos.toFixed(2)+'%';});
    return;
  }
  el._sig=sig;
  el.className='um um-avg avg-card';
  el.setAttribute('aria-label','Average ultrasound wait time');
  el.innerHTML=`
<div class="head"><div class="eyebrow">Avg Wait</div></div>
<div class="metric">
<div class="value">${bcEsc(avgTxt)}</div>
<div class="sub">${n?('Across '+n+' waiting '+(n===1?'patient':'patients')):'No patients waiting'}</div>
</div>
<div class="range-wrap">
<div class="range-top">
<div class="range-stat">
<div class="range-label">Shortest</div>
<div class="range-value">${lo===null?'—':bcEsc(fmtWait(lo))}</div>
</div>
<div class="range-stat right">
<div class="range-label">Longest</div>
<div class="range-value">${hi===null?'—':bcEsc(fmtWait(hi))}</div>
</div>
</div>
<div class="track-shell">
${n?`<div class="avg-tag" style="left:${pos.toFixed(2)}%">AVG</div>`:''}
<div class="track">
<div class="track-glow"style="width:${pos.toFixed(2)}%"></div>
<div class="track-fill"style="width:${pos.toFixed(2)}%"></div>
</div>
${n?`<div class="avg-marker" style="left:${pos.toFixed(2)}%"></div>`:''}
</div>
</div>
<div class="status is-${st.k}">
<div class="status-main">
<div class="status-icon"><svg viewBox="0 0 24 24"aria-hidden="true">${UST_AVG_ICONS[st.k]}</svg></div>
<div class="status-copy">
<div class="status-title">${st.t}</div>
<div class="status-sub">${st.s}</div>
</div>
</div>
${st.d?`<div class="delta">${bcEsc(st.d)}</div>`:''}
</div>`;
}

