function moveRoom(p,newRoom){
const old=p.room;
if(old===newRoom) return;
const stamp=new Date();
p.room=newRoom;
p.roomSince=stamp;
p.timeline.push({label:`Moved from ${old} to ${newRoom}`, at:stamp, meta:''});
notify('Patient moved',`${bcEsc(p.name)} · ${old} → ${newRoom}`, {icon:'move', color:STATUSES[p.status].color});
if(old!=='Lobby'&& !PATIENTS.some(x=>x.id!==p.id && isActive(x) && x.room===old))
notify(`${old} available`,'Ready for next patient', {icon:'room', color:'var(--s-admitted)'});
scheduleRender(function(){ if(activePatient===p.id) fillDrawer(p); });
}

function canDropRoom(p,target){
if(!p || !target || p.room===target) return false;
if(target==='Lobby'|| target==='Treatment') return true;
if(!ROOMS.includes(target)) return false;
return !PATIENTS.some(x=>x.id!==p.id && isActive(x) && x.room===target);
}

function showConfirm(title, okLabel, onOk, opts){
opts=opts||{};
document.getElementById('confirmTitle').textContent=title;
document.getElementById('confirmOk').textContent=okLabel;
const sub=document.getElementById('confirmSub');
sub.textContent=opts.sub||''; sub.style.display=opts.sub?'':'none';
const ok=document.getElementById('confirmOk');
ok.classList.toggle('danger', !!opts.danger);
ok.classList.remove('is-confirming','is-success');
const scrim=document.getElementById('confirmScrim'), box=document.getElementById('confirmBox');
const close=()=>{scrim.classList.remove('open');box.classList.remove('open');};
scrim.classList.add('open');box.classList.add('open');
{ const cb=document.getElementById('confirmCancel'); cb.textContent=opts.cancelLabel||'Cancel'; cb.onclick=()=>{ close(); if(opts.onCancel) opts.onCancel(); }; }
document.getElementById('confirmScrim').onclick=close;
if(opts.fancyConfirm){


box.classList.add('confirm-fancy');
ok.innerHTML='<span class="success-ring" aria-hidden="true"></span>'
+'<span class="confirm-content"><svg class="confirm-icon" viewBox="0 0 18 18" aria-hidden="true"><path d="M3.7 9.2 7.1 12.4 14.1 5.6" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="confirm-label"></span></span>'
+'<span class="shortcut" aria-hidden="true">↵</span>';
ok.querySelector('.confirm-label').textContent=okLabel;
const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches;
ok.onclick=()=>{
if(ok.classList.contains('is-confirming')) return;
if(reduce){ close(); onOk(); return; }
ok.classList.add('is-confirming');
const lbl=ok.querySelector('.confirm-label'); if(lbl) lbl.textContent='Confirming…';
setTimeout(()=>{ if(lbl) lbl.textContent='Confirmed'; ok.classList.add('is-success');
setTimeout(()=>{ close(); onOk(); }, 720); }, 520);
};
} else {
box.classList.remove('confirm-fancy');
ok.textContent=okLabel;
ok.onclick=()=>{close();onOk();};
}
}
 
