CLIENT_STEPS.map((lbl,i)=>{ const cls=i<cur?'done':(i===cur?'current':''); return`<div class="cl-step ${cls}"><div class="cl-node">${i<cur?CL_CHECK:''}</div>${withLabels?`<div class="cl-step-lbl">${lbl}</div>`:''}</div>`; }).join('')+
`</div>`;
