CLIENT_STEPS.map((lbl,i)=>{ const cls=i<cur?'done':(i===cur?'current':''); return`<div class="cl-vstep2 ${cls}"><span class="cl-vnode">${i<cur?CL_CHECK:''}</span><span class="cl-vlbl">${lbl}</span></div>`; }).join('')+
`</div>`;
