function rdEndedToday(){
return PATIENTS.filter(p=>p.rounds && p.rounds.outcome && p.rounds.outcome.at && rdRoundsDay(p.rounds.outcome.at)===rdRoundsDay(new Date()))
.sort((a,b)=>rdDate(b.rounds.outcome.at)-rdDate(a.rounds.outcome.at));
}
function rdPendingItems(p){
const r=p.rounds, out=[];
(r.diagnostics||[]).forEach(d=>{ if(d.status==='pending') out.push({kind:'diag',id:d.id,label:d.name,due:d.due||'Pending result'}); });
(r.tasks||[]).forEach(t=>{ if(t.status!=='done') out.push({kind:'task',id:t.id,label:t.label,due:t.due||'',urgent:t.urgent,assignee:t.assignee}); });
return out;
}
function rdOwnerDue(p){
const c=p.rounds.comms||{}; const hrs=(typeof c.intervalH==='number'?c.intervalH:12);
const ref=rdDate(c.lastAt)||rdDate(p.rounds.admittedAt); if(!ref) return null;
const over=(Date.now()-ref.getTime())/3600000 - hrs;
return over>0 ? fmtWait(Math.round(over*60)) : null;
}
function rdLikely(p){ const d=p.rounds.discharge||{}; return d.likely==='likely'||d.likely==='possible'; }





function rdDoc(id){ if(!id||id==='unassigned') return null; return rdAllDoctors().find(d=>d.id===id)||null; }
function rdDocShort(id){ const d=rdDoc(id); return d?drName(d.name):null; }
function rdCareList(p){ return (p.rounds&&p.rounds.care)||[]; }
function rdCareCurrent(p){ const c=rdCareList(p); return c.length?c[c.length-1]:null; }
function rdCareAdmit(p){ const c=rdCareList(p); return c.length?c[0]:null; }
function rdCareName(entry){ if(!entry) return null;
if(entry.docId){ const n=rdDocShort(entry.docId); if(n) return n; }
return entry.name||null; }
function rdCareInitials(entry){ if(!entry) return'—';
if(entry.docId){ const d=rdDoc(entry.docId); if(d) return d.initials; }
const n=(entry.name||'').replace(/^Dr\.?\s*/i,'').trim();
return n? n.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase() :'—';
}
function rdCareColor(entry){ if(entry&&entry.docId){ const d=rdDoc(entry.docId); if(d) return d.color; } return'var(--ink-400)'; }
function rdCarePush(p,docId,name,at){
const r=p.rounds; r.care=r.care||[];
r.care.push({id:rdId(),docId:docId||null,name:name||null,at:rdIso(at||new Date()),by:rdActorName()});
}
 
function rdSyncCare(p){
const r=p.rounds; if(!r) return false;
const cur=(p.doctor&&p.doctor!=='unassigned')?p.doctor:null;
if(!cur) return false;
const last=rdCareCurrent(p);
if(last&&last.docId===cur) return false;
if(!last&&!r.care.length&&r.admittedById===cur){ rdCarePush(p,cur,rdDocShort(cur),r.admittedAt); return true; }
rdCarePush(p,cur,rdDocShort(cur));
if(last) rdAudit(p,'Case handed to '+rdDocShort(cur)+(rdCareName(last)?(' from '+rdCareName(last)):''));
return true;
}


function rdCurrentDocId(p){
if(p.doctor&&p.doctor!=='unassigned') return p.doctor;
const c=rdCareCurrent(p); return c?c.docId:null;
}
function rdCurrentDocName(p){
const id=rdCurrentDocId(p); if(id) return rdDocShort(id);
const c=rdCareCurrent(p); return c?rdCareName(c):null;
}
 
function rdNextDocId(p){ const n=p.rounds&&p.rounds.next; return n?n.docId:null; }
function rdNextDocName(p){ const id=rdNextDocId(p); if(!id) return null;
return rdDocShort(id)||((p.rounds.next||{}).name||null); }
function rdContinuing(p){ const n=rdNextDocId(p); return !!n && n===rdCurrentDocId(p); }
function rdSetNext(p,docId){
if(!docId){ return rdClearNext(p); }
p.rounds.next={docId:docId,name:rdDocShort(docId),at:rdIso(new Date()),by:rdActorName()};
rdTouch(p, docId===rdCurrentDocId(p) ? ('Continuing with '+rdDocShort(docId)) : ('Next doctor · '+rdDocShort(docId)));
}
function rdClearNext(p){ if(!p.rounds.next) return; p.rounds.next=null; rdTouch(p,'Next doctor cleared'); }


function rdHandoffNow(p){
const id=rdNextDocId(p); if(!id) return;
p.rounds.next=null;
rdTakeCase(p,id);
}
function rdTakeCase(p,docId){
const prev=rdCareCurrent(p);
if(prev&&prev.docId===docId) return;
p.doctor=docId; 
rdCarePush(p,docId,rdDocShort(docId));
p.timeline.push({label:'Case taken by '+rdDocShort(docId), at:new Date(), meta:prev?('from '+(rdCareName(prev)||'—')):'Rounds'});
rdTouch(p,'Case taken by '+rdDocShort(docId)+(prev?(' from '+(rdCareName(prev)||'—')):''));
}



function rdAuth(p){
const r=p.rounds;
if(!r.auth){
r.auth={hours:[],
estimate:(r.financial&&r.financial.estimate!=null)?r.financial.estimate:null,
deposited:(r.financial&&r.financial.deposited!=null)?r.financial.deposited:null,
bill:null,cubexDob:false,payers:[],approvals:[]};
}
return r.auth;
}


function rdAuthRead(p){ return (p&&p.rounds&&p.rounds.auth)||null; }
function rdAuthHours(p){ const a=rdAuthRead(p); return a?(a.hours||[]).reduce((s,x)=>s+(+x.h||0),0):0; }


function rdLowEnd(a){ if(!a) return null; const hi=a.estimate!=null?+a.estimate:null; return a.estimateLow!=null&&+a.estimateLow>0?+a.estimateLow:(hi!=null?Math.round(hi*.8):null); }
function rdBalance(p){ const a=rdAuthRead(p);   /* n251: to the low end = low end − deposit (it was low end − charges, n117) */
const lo=rdLowEnd(a); if(lo==null||!(lo>0)) return null;
return lo-(+(a.deposited||0)); }
function rdMoneyTone(p){ const a=rdAuthRead(p), lo=rdLowEnd(a); if(!a||lo==null) return '';   /* amber from 80% of the low end, red past the high end */
const c=+(a.bill||0), hi=a.estimate!=null?+a.estimate:null; if(hi!=null&&c>hi) return 'over'; return c>=lo*.8?'warn':''; }
function rdRemain(v){ return v==null?'—':(v<0?'−'+rdMoney(-v):rdMoney(v)); }
function rdMoney(v){ return v==null?'—':('$'+Math.round(v).toLocaleString()); }
var RD_AUTH_SOON_H=12;   /* flow-round2-oct6: one "expiring" cutoff for the panel, the chips, the summary and the handoff */
function rdOwnerLine(p){ const due=rdOwnerDue(p); if(!due) return ''; const c=p.rounds.comms||{}, d=rdDate(c.lastAt);
return 'Owner update '+due+' overdue — '+(d?('last '+fmtTime(d)+' '+d.toLocaleDateString('en-US',{month:'short',day:'numeric'})+(c.lastBy?' by '+c.lastBy:'')):'no update since admission'); }
function rdAuthState(p){
const total=rdAuthHours(p); if(!total) return null;
const elapsed=(Date.now()-rdDate(p.rounds.admittedAt).getTime())/3600000;
const remaining=total-elapsed;
return {total:total,elapsed:elapsed,remaining:remaining,status:remaining<0?'over':(remaining<=RD_AUTH_SOON_H?'expiring':'ok')};
}
function rdBillDrift(p){
const a=rdAuthRead(p); if(!a) return null;
if(a.bill!=null&&a.deposited!=null&&a.bill>a.deposited) return a.bill-a.deposited;
return null;
}



function rdSyncFromPravix(p){
const r=p.rounds,u=p.ultrasound; if(!r||!u) return false;
const doneAt=u.completedAt?rdIso(u.completedAt):null;
if(!doneAt||r.usSyncedAt===doneAt) return false;
let changed=false;
const isUS=x=>/ultrasound|\baus\b/i.test(x.name||'');
const pend=(r.diagnostics||[]).find(x=>isUS(x)&&x.status==='pending');
if(pend){ pend.status='completed'; pend.at=doneAt; if(u.preliminaryFindings&&!pend.result) pend.result=u.preliminaryFindings; changed=true; }
else if(!(r.diagnostics||[]).some(x=>isUS(x)&&x.at===doneAt)){
r.diagnostics.push({id:rdId(),name:u.study||'Abdominal Ultrasound',result:u.preliminaryFindings||'Completed',status:'completed',at:doneAt,due:null,discussed:false,createdAt:doneAt});
changed=true;
}
r.usSyncedAt=doneAt;
if(changed) rdAudit(p,'Ultrasound result auto-resolved from Pravix');
return changed;
}

 
function rdSeriesAdd(p,key,v,v2){
const r=p.rounds; r.series=r.series||{};
(r.series[key]=r.series[key]||[]).push({at:rdIso(new Date()),v:(v==null?null:+v),v2:(v2==null?null:+v2)});
if(r.series[key].length>40) r.series[key]=r.series[key].slice(-40);
}
function rdSeriesLine(key,arr){
const m=RD_SERIES_META[key]||{label:key.toUpperCase()};
const f=x=>(x.v2!=null?(x.v+'/'+x.v2):String(x.v))+(m.unit||'');
if(!arr||!arr.length) return'';
if(arr.length===1) return m.label+' '+f(arr[0]);
return m.label+' '+f(arr[arr.length-2])+' → '+f(arr[arr.length-1]);
}



function rdDefaultService(p){
if(p.doctor && p.doctor!=='unassigned'&& IM_DOCTORS.some(d=>d.id===p.doctor)) return'im';
return'ecc';
}
function rdNormLoc(raw){


const t=String(raw||'').trim();
if(/^iso/i.test(t)) return'Isolation';
if(/^ward/i.test(t)) return'Wards';
if(/^icu/i.test(t)) return'ICU';
return RD_LOCATIONS.indexOf(t)>=0 ? t :'';
}
function rdDefaultLocation(p){
return rdNormLoc((p.rounds&&p.rounds.location)||p.room||'');
}
function rdSeedProblems(p){
const seen={};
return (p.reasonProblems||[]).filter(pr=>pr&&pr.label).map(pr=>{
const label=rdCap(pr.label); if(seen[label.toLowerCase()]) return null; seen[label.toLowerCase()]=1;
return {id:rdId(),label:label,active:true,resolvedAt:null};
}).filter(Boolean);
}
function rdSeedDiagnostics(p){
const out=[];
const u=p.ultrasound;
if(u&&u.status){
if(u.requestStatus==='completed'||u.completedAt){
out.push({id:rdId(),name:u.study||'Abdominal Ultrasound',result:u.preliminaryFindings||'Completed',status:'completed',at:rdIso(u.completedAt||new Date()),due:null});
}else if(u.status==='requested'||u.requestStatus){
out.push({id:rdId(),name:u.study||'Abdominal Ultrasound',result:'',status:'pending',at:null,due:'Requested in Flow'});
}
}
return out;
}
function rdEnroll(p){
const at=new Date();
if(p.rounds && !p.rounds.outcome){
 
p.rounds.location=rdDefaultLocation(p);
rdAudit(p,'Reconnected to active admission');
return;
}
const svc=rdDefaultService(p);
const admitDoc=(p.doctor&&p.doctor!=='unassigned')?rdDocShort(p.doctor):null;
p.rounds=rdNorm({
admittedAt:rdIso(at),
admittedBy:admitDoc, admittedById:(p.doctor&&p.doctor!=='unassigned')?p.doctor:null,
enrolledBy:CURRENT_USER,
admittingService:svc, service:svc,
location:rdDefaultLocation(p),
acuity:p.prio===1?'critical':(p.prio===2?'attention':'stable'),
newAdmit:true,
problems:rdSeedProblems(p),
events:[], diagnostics:rdSeedDiagnostics(p), treatments:[], tasks:[],
comms:{lastAt:null,lastBy:null,next:null,intervalH:12},
discharge:{likely:'not_today',checklist:null},
summary:null, review:{}, lastReviewSnapshot:null, snapshots:{},
handoff:null, financial:null, outcome:null,
care:(p.doctor&&p.doctor!=='unassigned')?[{id:rdId(),docId:p.doctor,name:rdDocShort(p.doctor),at:rdIso(at),by:CURRENT_USER}]:[],
audit:[{at:rdIso(at),by:CURRENT_USER,what:'Enrolled in Rounds from Flow'}]
});
try{ if(typeof fvRoundsPrefill==='function') fvRoundsPrefill(p,at); }catch(e){ console.warn('[rounds prefill]',e); }
p.timeline.push({label:'Enrolled in Rounds', at:at, meta:rdSvc(svc).label});
try{ notify('Added to Rounds', rdEsc(rdFullName(p))+' · New Admit · '+rdSvc(svc).label, {icon:'info', color:'var(--accent)'}); }catch(e){}
}
function rdOnFlowComplete(p, finalStatus){
if(finalStatus==='Admitted'){ rdEnroll(p); return; }
if(p.rounds && !p.rounds.outcome){
 
const type=(finalStatus==='Euthanized'||finalStatus==='Deceased')?finalStatus:'Discharged';
p.rounds.outcome={type:type,at:rdIso(new Date()),by:CURRENT_USER};
rdSnapshotToday(p);
rdAudit(p,'Admission closed from Flow · '+type);
}
}
function rdSetOutcome(p,type){
showConfirm('Mark '+rdFullName(p)+' as '+type.toLowerCase()+'?','Mark '+type.toLowerCase(), ()=>{
p.rounds.outcome={type:type,at:rdIso(new Date()),by:rdActorName()};
p.timeline.push({label:type, at:new Date(), meta:'Rounds · '+rdActorName()});
rdSnapshotToday(p);
rdExpanded=null;
rdTouch(p,'Admission ended · '+type);
if(p.status==='Hospitalized'&&!p.completed){ try{ completePatient(p, (type==='Euthanized'||type==='Deceased')?type:'Discharged'); }catch(e){} }   /* a direct admit leaves Flow too */
}, {sub:'The admission closes and moves to the Rounds archive. The full record is preserved.',noDefault:true});   /* n311 */
}
function rdSetLocation(p,loc){
const old=p.rounds.location;
if(rdNormLoc(old)===loc) return;   /* n321 */
p.rounds.location=loc;
p.room=loc; 
rdTouch(p,'Location '+(old||'—')+' → '+loc);
}
function rdSetService(p,svc){
const old=p.rounds.service;
if(old===svc) return;
p.rounds.service=svc;
p.timeline.push({label:'Service changed', at:new Date(), meta:rdSvc(old).label+' → '+rdSvc(svc).label});
rdTouch(p,'Service '+rdSvc(old).label+' → '+rdSvc(svc).label);
}
function rdSetAcuity(p,a){
if(p.rounds.acuity===a) return;
p.rounds.acuity=a;
rdTouch(p,'Acuity → '+RD_ACUITY[a].label);
}

 
function rdSnapState(p){
const r=p.rounds;
return {
at:rdIso(new Date()),
day:rdDayNum(p),
service:r.service, location:r.location, acuity:r.acuity,
problems:(r.problems||[]).filter(x=>x.active!==false).map(x=>x.label),
diag:(r.diagnostics||[]).reduce((m,d)=>{ m[d.name]=(d.status||'pending')+(d.result?(' | '+d.result):''); return m; },{}),
tx:(r.treatments||[]).map(t=>t.name+(t.detail?(' — '+t.detail):'')),
tasksOpen:(r.tasks||[]).filter(t=>t.status!=='done').map(t=>t.label),
tasksDone:(r.tasks||[]).filter(t=>t.status==='done').map(t=>t.id),
eventCount:(r.events||[]).length,
commLastAt:(r.comms&&r.comms.lastAt)||null,
summary:(r.summary&&r.summary.text)||'',
admitType:r.admitType||'clinical',
flags:(r.flags||[]).map(f=>f.label),
careIds:(r.care||[]).map(c=>c.id),
nextDocId:(r.next&&r.next.docId)||null,
contIds:(r.contingencies||[]).map(c=>c.id),
authTotal:rdAuthHours(p),
seriesLast:(function(){ const out={}; const s=r.series||{}; Object.keys(s).forEach(k=>{ const a=s[k]; if(a&&a.length) out[k]=a[a.length-1].at; }); return out; })()
};
}
function rdSnapshotToday(p){
const r=p.rounds; if(!r) return;
r.snapshots=r.snapshots||{};
r.snapshots[rdDayKey(new Date())]=rdSnapState(p);
}
function rdSnapshotFor(p,dayKey){
const snaps=(p.rounds&&p.rounds.snapshots)||{};
if(snaps[dayKey]) return snaps[dayKey];
const keys=Object.keys(snaps).filter(k=>k<=dayKey).sort();
return keys.length? snaps[keys[keys.length-1]] : null;
}

 
function rdDiff(p){
const r=p.rounds, s=r.lastReviewSnapshot;
if(!s) return null;
const out=[], sAt=rdDate(s.at);
(r.events||[]).forEach(e=>{ if(rdDate(e.at)>sAt) out.push({tag:'NEW',text:e.text,time:rdT(e.at)}); });
(r.diagnostics||[]).forEach(d=>{
const prev=s.diag&&s.diag[d.name];
const cur=(d.status||'pending')+(d.result?(' | '+d.result):'');
if(prev==null){ out.push({tag:d.status==='completed'?'NEW RESULT':'ORDERED',text:d.name+(d.result?(' — '+d.result):''),time:rdT(d.at)}); }
else if(prev!==cur){ out.push({tag:d.status==='completed'?(prev.indexOf('completed')===0?'CHANGED':'NEW RESULT'):'CHANGED',text:d.name+(d.result?(' — '+d.result):''),time:rdT(d.at)}); }
});
const sTx=s.tx||[];
(r.treatments||[]).forEach(t=>{ const cur=t.name+(t.detail?(' — '+t.detail):''); if(sTx.indexOf(cur)<0) out.push({tag:'ADDED',text:cur,time:''}); });
sTx.forEach(x=>{ if(!(r.treatments||[]).some(t=>(t.name+(t.detail?(' — '+t.detail):''))===x)) out.push({tag:'REMOVED',text:x,time:''}); });
const sProbs=s.problems||[];
(r.problems||[]).forEach(x=>{ if(x.active!==false && sProbs.indexOf(x.label)<0) out.push({tag:'ADDED',text:x.label,time:''}); });
(r.problems||[]).forEach(x=>{ if(x.active===false && sProbs.indexOf(x.label)>=0) out.push({tag:'RESOLVED',text:x.label,time:''}); });
(r.tasks||[]).forEach(t=>{ if(t.status==='done'&& (s.tasksDone||[]).indexOf(t.id)<0) out.push({tag:'COMPLETED',text:t.label,time:rdT(t.doneAt)}); });
if(s.acuity && s.acuity!==r.acuity) out.push({tag:'CHANGED',text:'Acuity '+RD_ACUITY[s.acuity].label+' → '+RD_ACUITY[r.acuity].label,time:''});
if((r.comms&&r.comms.lastAt)&&r.comms.lastAt!==s.commLastAt) out.push({tag:'OWNER',text:'Owner updated'+(r.comms.lastBy?(' · '+r.comms.lastBy):''),time:rdT(r.comms.lastAt)});
(r.care||[]).forEach((c,i)=>{ if(i>0&&(s.careIds||[]).indexOf(c.id)<0) out.push({tag:'HANDOFF',text:'Case taken by '+(rdCareName(c)||'—'),time:rdT(c.at)}); });
(r.contingencies||[]).forEach(c=>{ if((s.contIds||[]).indexOf(c.id)<0) out.push({tag:'ORDER',text:'If '+c.trigger.toLowerCase()+' → '+c.action,time:rdT(c.at)}); });
(r.flags||[]).forEach(f=>{ if((s.flags||[]).indexOf(f.label)<0) out.push({tag:'FLAG',text:f.label,time:''}); });
const authNow=rdAuthHours(p);
if(typeof s.authTotal==='number'&&authNow>s.authTotal) out.push({tag:'AUTH',text:'Authorization extended +'+(authNow-s.authTotal)+'h ('+authNow+'h total)',time:''});
Object.keys(r.series||{}).forEach(k=>{
const a=r.series[k]; if(!a||!a.length) return;
const last=a[a.length-1];
if(!s.seriesLast||s.seriesLast[k]!==last.at) out.push({tag:'TREND',text:rdSeriesLine(k,a),time:rdT(last.at)});
});
return out;
}

 
function rdGenerateSummary(p){
const r=p.rounds, s=[];
s.push('Hospital Day '+rdDayNum(p)+' · '+rdSvc(r.service).label+(r.admitType!=='clinical'?(' · '+RD_ADMIT_TYPES[r.admitType]):'')+'.');
if((r.flags||[]).length) s.push('Flags: '+r.flags.map(f=>f.label).join(', ')+'.');
const as=rdAuthState(p);
if(as) s.push(as.status==='over'
? ('Authorization exceeded — '+Math.round(as.elapsed)+'h elapsed of '+as.total+'h approved.')
: ('Authorized '+as.total+'h — '+Math.round(as.elapsed)+'h elapsed'+(as.status==='expiring'?', expiring soon':'')+'.'));
const probs=(r.problems||[]).filter(x=>x.active!==false).map(x=>x.label);
if(probs.length) s.push('Active problems: '+probs.join(', ').toLowerCase()+'.');
const evs=(r.events||[]).slice().sort((a,b)=>rdDate(a.at)-rdDate(b.at));
const recent=evs.filter(e=>Date.now()-rdDate(e.at).getTime()<16*3600000);
if(recent.length){ const lastE=recent[recent.length-1]; s.push(recent.length+' overnight event'+(recent.length>1?'s':'')+'; most recent — '+lastE.text.toLowerCase()+' at '+rdT(lastE.at)+'.'); }
else if(evs.length===0) s.push('No events recorded since admission.');
else s.push('Quiet overnight — no new events.');
const done=(r.diagnostics||[]).filter(d=>d.status==='completed');
const pend=(r.diagnostics||[]).filter(d=>d.status==='pending');
if(done.length) s.push('Diagnostics: '+done.map(d=>d.name+(d.result?(' — '+d.result):'')).join('; ')+'.');
if(pend.length) s.push('Pending: '+pend.map(d=>d.name).join(', ')+'.');
const tx=(r.treatments||[]).map(t=>t.name).filter(Boolean);
if(tx.length) s.push('Currently on '+tx.join(', ')+'.');
const openT=(r.tasks||[]).filter(t=>t.status!=='done');
if(openT.length) s.push('Next: '+openT.slice(0,3).map(t=>t.label+(t.due?(' · '+t.due):'')).join('; ')+'.');
const conts=(r.contingencies||[]).filter(x=>x.active!==false);
if(conts.length) s.push('Standing orders: '+conts.map(x=>'if '+x.trigger.toLowerCase()+' → '+x.action).join('; ')+'.');
const c=r.comms||{};
const odue=rdOwnerLine(p);
if(odue) s.push(odue+(c.next?('; next — '+c.next):'')+'.');
else if(c.lastAt) s.push('Owner last updated '+rdT(c.lastAt)+(c.lastBy?(' by '+c.lastBy):'')+(c.next?('; next — '+c.next):'')+'.');
else if(c.next) s.push('Owner update planned — '+c.next+'.');
else if(rdOwnerDue(p)) s.push('Owner update is due.');
return s.join('\n');
}
function rdGenerateHandoff(p){
const r=p.rounds, s=[];
s.push(RD_ACUITY[r.acuity].label+' · '+rdSvc(r.service).label+' · '+(r.location||'—')+' · Day '+rdDayNum(p)+'.');
const cc=rdCareCurrent(p), ca=rdCareAdmit(p);
if(cc) s.push('With '+(rdCareName(cc)||'—')+(ca&&ca.id!==cc.id?(' since '+rdT(cc.at)+'; admitted by '+(rdCareName(ca)||'—')):'')+'.');
const evs=(r.events||[]).filter(e=>Date.now()-rdDate(e.at).getTime()<16*3600000);
s.push(evs.length? ('Overnight: '+evs.map(e=>e.text.toLowerCase()).join('; ')+'.') :'Stable — nothing new to hand off.');
const pend=rdPendingItems(p);
if(pend.length) s.push('Outstanding: '+pend.map(x=>x.label+(x.due?(' · '+x.due):'')).join('; ')+'.');
const conts=(r.contingencies||[]).filter(x=>x.active!==false);
if(conts.length) s.push('Contingencies: '+conts.map(x=>'if '+x.trigger.toLowerCase()+' → '+x.action).join('; ')+'.');
if((r.flags||[]).length) s.push('Flags: '+r.flags.map(f=>f.label).join(', ')+'.');
const as=rdAuthState(p);
if(as&&as.status!=='ok') s.push(as.status==='over'?'Authorization exceeded — owner conversation needed.':'Authorization expires in '+fmtWait(Math.max(0,Math.round(as.remaining*60)))+'.');
const c=r.comms||{};
{ const odue=rdOwnerLine(p); if(odue) s.push(odue+'.'); }
if(c.next) s.push('Owner expects an update '+c.next.toLowerCase()+'.');
if(c.window) s.push('Owner constraint: '+c.window+'.');
return s.join('\n');
}

 
function rdParseTime(text){
let at=null, rest=text;
let m=rest.match(/\b(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);
if(!m) m=rest.match(/\b(?:at\s+)(\d{1,2})(?::(\d{2}))?\b/);
if(m){
let h=parseInt(m[1],10)%12; const min=m[2]?parseInt(m[2],10):0;
const ap=(m[3]||'').toLowerCase();
if(ap==='pm') h+=12;
if(!ap && parseInt(m[1],10)>=13) h=parseInt(m[1],10);
const d=new Date(); d.setHours(h,min,0,0);
if(d.getTime()>Date.now()+5*60000) d.setDate(d.getDate()-1); 
at=d; rest=(rest.slice(0,m.index)+rest.slice(m.index+m[0].length)).replace(/\s{2,}/g,' ').trim();
}
return {at:at, rest:rest, dueText:m? m[0].replace(/^at\s+/i,'').toUpperCase().replace(/\s+/g,' ') : null};
}
function rdParseQuick(p, raw){
const text=String(raw||'').trim(); if(!text) return null;
const low=text.toLowerCase();
 
let cm=text.match(/^if\s+(.+)$/i);
if(cm){
const parts=cm[1].split(/\s*(?:→|->|—>|,?\s*then\s+|:)\s*/);
if(parts.length>=2&&parts[1].trim()){
const trig=rdCap(parts[0].trim()), act=rdCap(parts.slice(1).join(' — ').trim());
return {kind:'cont',title:'Contingency',preview:'IF '+trig+' → '+act,
apply:function(){ p.rounds.contingencies.push({id:rdId(),trigger:trig,action:act,active:true,by:rdActorName(),at:rdIso(new Date())}); rdTouch(p,'Contingency · if '+trig); }};
}
}
 
cm=low.match(/^flag[:\s]+(.+)$/);
if(cm){ const label=rdCap(cm[1]);
return {kind:'flag',title:'Safety Flag',preview:label,
apply:function(){ p.rounds.flags.push({id:rdId(),label:label,kind:'safety'}); rdTouch(p,'Flag added · '+label); }}; }
 
cm=text.match(/^incident[:\s]+(.+)$/i);
if(cm){ const t=rdCap(cm[1]);
return {kind:'incident',title:'Incident',preview:t,
apply:function(){ p.rounds.events.push({id:rdId(),at:rdIso(new Date()),text:t,by:rdActorName(),kind:'incident'});
p.rounds.tasks.push({id:rdId(),label:'Disclose incident to owner',due:null,assignee:null,status:'pending',doneAt:null,urgent:true,createdAt:rdIso(new Date())});
rdTouch(p,'Incident recorded'); }}; }
 
cm=low.match(/^(pcv\/?ts|pcv|na|k|bg|glu|bp|o2|lac|temp|hr|rr)\s*[:\s]\s*([\d.]+)(?:\s*\/\s*([\d.]+))?\s*%?$/);
if(cm){
let key=cm[1].replace('/','').replace('pcvts','pcv'); if(key==='glu') key='bg';
if(RD_SERIES_META[key]){
const v=parseFloat(cm[2]), v2=cm[3]!=null?parseFloat(cm[3]):null;
const m=RD_SERIES_META[key];
return {kind:'series',title:'Trend',preview:m.label+' '+(v2!=null?(v+'/'+v2):v)+(m.unit||''),
apply:function(){ rdSeriesAdd(p,key,v,v2); rdTouch(p,'Trend · '+m.label); }};
}
}
 
if(/^owner\b/.test(low)||/\bowner (update|call)\b/.test(low)){
const next=rdCap(text.replace(/^owner\s*(update|call)?\s*/i,'').trim())||'Update owner';
return {kind:'comm',title:'Communication',preview:'Owner update · '+next,
apply:function(){ p.rounds.comms.next=next; rdTouch(p,'Owner plan · '+next); }};
}
 
let m=low.match(/^(?:add\s+)?problem[:\s]+(.+)$/);
if(m){ const label=rdCap(m[1]);
return {kind:'problem',title:'Active Problem',preview:label,
apply:function(){ p.rounds.problems.push({id:rdId(),label:label,active:true,resolvedAt:null}); rdTouch(p,'Problem added · '+label); }}; }
 
m=low.match(/^(?:tx|treatment|start)[:\s]+(.+)$/);
if(m){ const t=rdCap(m[1]);
return {kind:'tx',title:'Treatment',preview:t,
apply:function(){ const parts=t.split(/\s[-–—]\s|,\s*/); p.rounds.treatments.push({id:rdId(),name:parts[0],detail:parts.slice(1).join(', ')}); rdTouch(p,'Treatment added · '+parts[0]); }}; }
 
if(/^(repeat|recheck|check|give|transition|call|schedule|walk|feed|d\/c|discontinue|remove|pull|start)\b/.test(low)){
const pt=rdParseTime(text);
const label=rdCap(pt.rest);
const due=pt.at? fmtTime(pt.at) : (pt.dueText||null);
return {kind:'task',title:'Task',preview:label+(due?(' · '+due):''),
apply:function(){ p.rounds.tasks.push({id:rdId(),label:label,due:due,assignee:null,status:'pending',doneAt:null,urgent:false}); rdTouch(p,'Task added · '+label); }}; }
 
m=low.match(/^(?:dx|diagnostic|order)[:\s]+(.+)$/);
if(m){ const nm=rdCap(m[1]);
return {kind:'diag',title:'Diagnostic',preview:nm+' · Pending',
apply:function(){ p.rounds.diagnostics.push({id:rdId(),name:nm,result:'',status:'pending',at:null,due:null}); rdTouch(p,'Diagnostic ordered · '+nm); }}; }
 
const pt=rdParseTime(text);
const evText=rdCap(pt.rest);
const at=pt.at||new Date();
return {kind:'event',title:'Event',preview:evText+' · '+fmtTime(at),
apply:function(){ p.rounds.events.push({id:rdId(),at:rdIso(at),text:evText,by:rdActorName(),kind:'clinical'}); rdTouch(p,'Event · '+evText); }};
}

 
function rdMarkReviewed(p){
const r=p.rounds;
r.review=r.review||{};
r.review[rdReviewKey()]={by:rdActorName(),at:rdIso(new Date())};
r.lastReviewSnapshot=rdSnapState(p);
if(r.newAdmit){ r.newAdmit=false; }
rdSnapshotToday(p);
rdTouch(p,'Rounds reviewed · '+rdShift,true);
}



