/* n314 · Charts: a small change draws small (the scale spans at least 10% of the value, so K 4.0 → 4.1 no longer fills the
   height like 10.13 → 5.27), the latest reading is marked, and VoiceOver hears every reading with its time */
function rdSpark(arr,key){
const pts0=arr.filter(x=>x&&x.v!=null), vals=pts0.map(x=>+x.v);
if(vals.length<2) return'';
let min=Math.min.apply(null,vals), max=Math.max.apply(null,vals);
const floor=Math.max(Math.abs(max),Math.abs(min))*0.10||1; if(max-min<floor){ const mid=(max+min)/2; min=mid-floor/2; max=mid+floor/2; }
const span=(max-min)||1, w=64,h=18,step=w/(vals.length-1);
const xy=vals.map((v,i)=>[i*step,h-2-((v-min)/span)*(h-4)]);
const pts=xy.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' '), L=xy[xy.length-1];
const up=vals[vals.length-1]>=vals[0];
const m=(typeof RD_SERIES_META!=='undefined'&&key&&RD_SERIES_META[key])||{label:key?String(key).toUpperCase():'Trend'};
const said=pts0.map(x=>(x.v2!=null?x.v+'/'+x.v2:x.v)+(m.unit||'')+(x.at?' at '+rdT(x.at):'')).join(', ');
const label=m.label+', '+pts0.length+' readings: '+said;
return`<svg class="rd-spark ${up?'up':'down'}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${rdEsc(label)}"><polyline points="${pts}"/><circle class="rd-spark-last" cx="${Math.min(L[0],w-2).toFixed(1)}" cy="${L[1].toFixed(1)}" r="2"/></svg>`;
}
function rdTrendsHTML(p){
const pid=p.id, s=p.rounds.series||{};
const keys=Object.keys(s).filter(k=>s[k]&&s[k].length);
return`<div class="rd-sec">
    <div class="rd-sec-h">Trends</div>
    ${keys.length?`<div class="rd-trends">${keys.map(k=>`
      <div class="rd-trend"><span class="t">${rdEsc(rdSeriesLine(k,s[k]))}</span>${rdSpark(s[k],k)}<span class="w">${rdT(s[k][s[k].length-1].at)}</span>
        <button class="x" data-act="trend-undo" data-pid="${pid}" data-key="${k}" title="Remove last value" aria-label="${rdEsc('Remove last value: '+rdSeriesLine(k,s[k]))}">${PVX_GI.xmark}</button></div>`).join('')}</div>`
    :`<div class="rd-empty-line">Serial values chart themselves — type “pcv 27” or “na 154” below or in quick add.</div>`}
    ${rdSecAdd(pid,'series','+ Value — “pcv 27/6.0”, “na 154”, “o2 60”')}
  </div>`;
}
