function rdRankKey(e,btn){ if(e.key!=='ArrowUp'&&e.key!=='ArrowDown') return; e.preventDefault(); e.stopPropagation(); rdRankMove(btn.dataset.pid,e.key==='ArrowUp'?-1:1); }
