function rdDemoPatient(o,r){
const hrs=o._hrsAgo||20; delete o._hrsAgo;
const at=new Date(Date.now()-hrs*3600000);
const p=patient(Object.assign({
_demo:true, status:'Admitted', completed:true, active:false, completedAt:at, arrival:new Date(at.getTime()-4*3600000),
prio:2, room:'ICU', doctor:'unassigned', species:'Canine', timeline:[{label:'Checked in',at:new Date(at.getTime()-4*3600000),meta:''},{label:'Admitted',at:at,meta:'From Diagnostics'}]
},o));
r=r||{};
p.rounds=rdNorm(Object.assign({
admittedAt:rdIso(at), admittedBy:o._by||null, enrolledBy:'Flow',
admittingService:r.service||'ecc', newAdmit:false,
comms:{lastAt:rdIso(new Date(at.getTime()+2*3600000)),lastBy:o._by||'Care Team',next:null,intervalH:12}
},r));
p.rounds.assessment=r.assessment||'';
return p;
}
