    try{ if(ready&&rdFind(id)&&typeof renderRdCensus==='function'){ done(); rdExpanded=id; renderRdCensus(true);
      setTimeout(()=>{ const row=document.querySelector('.rd-row[data-pid="'+id+'"]'); if(row) row.scrollIntoView({block:'start'}); },60); return; } }catch(e){}
    if(!ready){ n=0; setTimeout(tryOpen,300); return; }
