    const isHead=t.matches('#rdList .rd-sechead[data-act]'), isRow=!isHead&&t.matches('#rdList .rd-row button[data-act=toggle]'); if(!isHead&&!isRow) return;
    const k=e.key;
    if((k==='ArrowDown'||k==='ArrowUp')&&!e.altKey){ const l=items(), i=l.indexOf(t), n=l[i+(k==='ArrowDown'?1:-1)]; e.preventDefault(); if(n){ n.focus(); try{ n.scrollIntoView({block:'nearest'}); }catch(x){} } return; }
    if(k!=='ArrowLeft'&&k!=='ArrowRight') return; e.preventDefault();
    const rtl=getComputedStyle(t).direction==='rtl'; const open=(k==='ArrowRight')!==rtl;
    if(e.altKey){ setAll(!open,isHead?t:headOf(t)); return; }
